<script setup>
import { Head, Link, useForm } from '@inertiajs/vue3'; import AppLayout from '@/Layouts/AppLayout.vue'; import Icon from '@/Components/UI/Icon.vue'; import HrNav from '../Partials/HrNav.vue'; import AttendanceForm from './AttendanceForm.vue';
defineOptions({layout:AppLayout}); const props=defineProps({record:Object,employees:[Array,Object]}); const local=(value)=>value?value.slice(0,16):''; const form=useForm({employee_uuid:props.record.employee.uuid,started_at:local(props.record.started_at),ended_at:local(props.record.ended_at),observation:props.record.observation??''}); const submit=()=>form.put(`/administration/attendance/${props.record.uuid}`);
</script>
<template><Head title="Corriger une présence"/><div class="space-y-5"><HrNav/><header class="flex gap-3"><Link href="/administration/attendance" class="flex h-9 w-9 items-center justify-center rounded-lg border border-gray-200 bg-white"><Icon name="arrow-left"/></Link><div><p class="text-xs font-bold uppercase tracking-wide text-violet-600">Présences</p><h1 class="font-heading text-2xl font-bold text-slate-800 dark:text-white">Corriger la session</h1><p class="text-xs font-mono text-slate-400">{{ record.uuid }}</p></div></header><AttendanceForm :form="form" :employees="employees" cancel-href="/administration/attendance" submit-label="Enregistrer la correction" @submit="submit"/></div></template>
